import { useEffect, useState } from "react";
import { AppShell, type PrimaryRouteName } from "./components/appShell";
import { HomeDashboard } from "./components/home";
import { DEFAULT_CONFIG, type InterviewConfig, makeId, nowIso } from "./components/shared";
import { importToServer, saveRecordOnServer } from "./lib/apiClient";
import { repairAppState, repairText } from "./lib/copy";
import { buildInterviewReport, createPosition, createProfile, recomputePosition, recomputeProfile, saveQuestionFromCueCard, toWorkspace } from "./lib/interviewEngine";
import { navigateTo, parseRoute } from "./lib/router";
import { clearAppState, loadAppState, saveAppState } from "./lib/store";
import type {
  AnswerCueCard,
  AppState,
  ConversationMessage,
  EvidenceItem,
  InterviewAiMeta,
  InterviewQuestion,
  InterviewRecord,
  InterviewReport,
  MockMessage,
  MockTurn,
  Position,
  SpeechMetrics,
} from "./types";
import { LiveAssistantDashboard, InterviewRoomView } from "./components/live";
import { AccountModal, RecordReportView, RecordsView } from "./components/records";
import { JdWorkspace } from "./components/jd";
import { QuestionsWorkspace } from "./components/questions";
import { ResumeWorkspacePage } from "./components/resume";

export function App() {
  const [appState, setAppState] = useState<AppState>(() => repairAppState(loadAppState()));
  const [routePath, setRoutePath] = useState(() => (typeof window === "undefined" ? "/" : window.location.pathname));
  const [accountOpen, setAccountOpen] = useState(false);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig>(DEFAULT_CONFIG);
  const [homeDrawerOpen, setHomeDrawerOpen] = useState(false);

  useEffect(() => saveAppState(appState), [appState]);

  useEffect(() => {
    const onPopState = () => setRoutePath(window.location.pathname);
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const { profile, positions, activePositionId, interviewRecords, activeRecordId } = appState;
  const activePosition = positions.find((position) => position.id === activePositionId) ?? positions[0];
  const activeWorkspace = activePosition ? toWorkspace(profile, activePosition) : null;
  const route = parseRoute(routePath);
  const activeRecord =
    route.name === "recordDetail"
      ? interviewRecords.find((record) => record.id === route.recordId) ?? interviewRecords.find((record) => record.id === activeRecordId) ?? interviewRecords[0]
      : interviewRecords.find((record) => record.id === activeRecordId) ?? interviewRecords[0];

  const activeNav: PrimaryRouteName = route.name === "recordDetail" ? "records" : route.name;

  const openRoute = (path: string, options?: { replace?: boolean }) => {
    navigateTo(path, options);
    setRoutePath(path);
  };

  const patchState = (updater: (current: AppState) => AppState) => {
    setAppState((current) => repairAppState(updater(current)));
  };

  const setPositions = (updater: (items: Position[]) => Position[], nextActiveId = activePositionId) => {
    patchState((current) => ({ ...current, positions: updater(current.positions), activePositionId: nextActiveId }));
  };

  const createOrUpdatePosition = (jobText: string) => {
    const trimmed = jobText.trim();
    if (!trimmed) return;

    if (activePosition && trimmed === activePosition.jobText.trim()) {
      const recomputed = recomputePosition({ ...activePosition, jobText: trimmed }, profile);
      setPositions((items) => items.map((item) => (item.id === activePosition.id ? recomputed : item)), recomputed.id);
      setHomeDrawerOpen(false);
      return;
    }

    const existing = positions.find((position) => position.jobText.trim() === trimmed);
    if (existing) {
      patchState((current) => ({ ...current, activePositionId: existing.id }));
      setHomeDrawerOpen(false);
      return;
    }

    const position = createPosition(trimmed, profile);
    const next = repairAppState({
      ...appState,
      positions: [position, ...appState.positions],
      activePositionId: position.id,
    });
    setAppState(next);
    setHomeDrawerOpen(false);
    void importToServer(next).catch(() => undefined);
  };

  const updateResume = (resumeText: string) => {
    patchState((current) => {
      const nextProfile = recomputeProfile(resumeText, current.profile);
      return {
        ...current,
        profile: nextProfile,
        positions: current.positions.map((position) => recomputePosition(position, nextProfile)),
      };
    });
  };

  const updateEvidence = (items: EvidenceItem[]) => {
    patchState((current) => {
      const nextProfile = { ...current.profile, evidenceLibrary: items };
      return {
        ...current,
        profile: nextProfile,
        positions: current.positions.map((position) => recomputePosition(position, nextProfile)),
      };
    });
  };

  const updateQuestion = (questionId: string, patch: Partial<InterviewQuestion>) => {
    if (!activePosition) return;
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id
          ? {
              ...position,
              questions: position.questions.map((question) =>
                question.id === questionId ? { ...question, ...patch, lastReviewedAt: nowIso() } : question,
              ),
              updatedAt: nowIso(),
            }
          : position,
      ),
    );
  };

  const addQuestion = (payload: Pick<InterviewQuestion, "question" | "category" | "difficulty"> & { answer?: string; notes?: string }) => {
    if (!activePosition) return;
    const question: InterviewQuestion = {
      id: makeId("q-manual"),
      category: repairText(payload.category),
      question: repairText(payload.question),
      difficulty: repairText(payload.difficulty),
      reason: "鐢ㄦ埛鎵嬪姩琛ュ厖鐨勯棶棰橈紝渚涢棶棰樺簱鍜屽悗缁粌涔犲鐢ㄣ€?,
      evidenceIds: [],
      source: "manual",
      priority: true,
      notes: repairText(payload.notes),
      answer: repairText(payload.answer),
      cueCardIds: [],
      lastReviewedAt: nowIso(),
    };
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id ? { ...position, questions: [question, ...position.questions], updatedAt: nowIso() } : position,
      ),
    );
  };

  const addQuestionFromCueCard = (card: AnswerCueCard) => {
    if (!activePosition) return;
    const question = saveQuestionFromCueCard(card);
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id ? { ...position, questions: [question, ...position.questions], updatedAt: nowIso() } : position,
      ),
    );
  };

  const saveInterviewRecord = (payload: {
    mode: "live" | "mock";
    title: string;
    transcript: MockMessage[];
    cueCards: AnswerCueCard[];
    turn?: MockTurn;
    speechMetrics?: SpeechMetrics[];
    report?: InterviewReport;
    conversationHistory?: ConversationMessage[];
    aiMeta?: InterviewAiMeta;
  }) => {
    if (!activePosition) return;
    const turns = payload.turn
      ? [...activePosition.mockTurns.filter((item) => item.questionId !== payload.turn?.questionId), payload.turn]
      : activePosition.mockTurns;
    const report = payload.report ?? buildInterviewReport(turns, activePosition.questions, activePosition.matchReport);
    const record: InterviewRecord = {
      id: makeId("record"),
      positionId: activePosition.id,
      mode: payload.mode,
      title: payload.title,
      createdAt: nowIso(),
      transcript: payload.transcript,
      cueCards: payload.cueCards,
      questionIds: Array.from(new Set(payload.cueCards.flatMap((card) => [card.id, ...card.evidenceIds]))),
      speechMetrics: payload.speechMetrics ?? (payload.turn?.speechMetrics ? [payload.turn.speechMetrics] : []),
      report,
      summary: payload.report?.summary ?? `${payload.mode === "live" ? "瀹炴椂鍔╂墜" : "妯℃嫙闈㈣瘯"}璁板綍宸蹭繚瀛橈紝鐢熸垚 ${payload.cueCards.length} 寮犳彁璇嶅崱銆俙,
      conversationHistory: payload.conversationHistory,
      aiMeta: payload.aiMeta,
    };

    const next = repairAppState({
      ...appState,
      activeRecordId: record.id,
      interviewRecords: [record, ...appState.interviewRecords],
      positions: appState.positions.map((position) =>
        position.id === activePosition.id ? { ...position, mockTurns: turns, report, updatedAt: nowIso() } : position,
      ),
    });

    setAppState(next);
    void saveRecordOnServer(record).catch(() => undefined);
    openRoute(`/records/${record.id}`);
  };

  const clearAll = () => {
    clearAppState();
    setAppState(repairAppState({ profile: createProfile(""), positions: [], activePositionId: "", interviewRecords: [], activeRecordId: "", aiMode: false }));
    openRoute("/", { replace: true });
    setAccountOpen(false);
  };

  const startConfiguredMock = (config = interviewConfig) => {
    setInterviewConfig(config);
    openRoute("/mock");
  };

  return (
    <AppShell
      activeNav={activeNav}
      accountName={profile.displayName || "鍊欓€変汉"}
      onNavigate={(nav) => {
        if (nav === "home") openRoute("/");
        if (nav === "live") openRoute("/live");
        if (nav === "mock") openRoute("/mock");
        if (nav === "jd") openRoute("/jd");
        if (nav === "questions") openRoute("/questions");
        if (nav === "resume") openRoute("/resume");
        if (nav === "records") openRoute("/records");
      }}
      onAccount={() => setAccountOpen(true)}
    >
      {route.name === "home" && (
        <HomeDashboard
          workspace={activeWorkspace}
          position={activePosition}
          positions={positions}
          activePositionId={activePositionId}
          drawerOpen={homeDrawerOpen}
          onToggleDrawer={() => setHomeDrawerOpen((current) => !current)}
          onCloseDrawer={() => setHomeDrawerOpen(false)}
          onSubmitJd={createOrUpdatePosition}
          onSelectPosition={(positionId) => patchState((current) => ({ ...current, activePositionId: positionId }))}
          onLive={() => openRoute("/live")}
          onOpenMock={() => openRoute("/mock")}
        />
      )}

      {route.name === "live" && activeWorkspace && activePosition && (
        <LiveAssistantDashboard
          workspace={activeWorkspace}
          profile={profile}
          position={activePosition}
          onSaveRecord={saveInterviewRecord}
          onSaveQuestion={addQuestionFromCueCard}
        />
      )}

      {route.name === "mock" && activeWorkspace && activePosition && (
        <InterviewRoomView
          workspace={activeWorkspace}
          profile={profile}
          position={activePosition}
          onSaveRecord={saveInterviewRecord}
          onSaveQuestion={addQuestionFromCueCard}
          config={interviewConfig}
        />
      )}

      {route.name === "jd" && (
        <JdWorkspace
          workspace={activeWorkspace}
          profile={profile}
          position={activePosition}
          onSubmitJd={createOrUpdatePosition}
          onOpenLive={() => openRoute("/live")}
          onOpenMock={() => openRoute("/mock")}
          onCreateQuestions={(items) => items.forEach((item) => addQuestion(item))}
        />
      )}

      {route.name === "questions" && (
        <QuestionsWorkspace
          workspace={activeWorkspace}
          onUpdateQuestion={updateQuestion}
          onAddQuestion={addQuestion}
          onOpenLive={() => openRoute("/live")}
          onOpenMock={() => startConfiguredMock()}
        />
      )}

      {route.name === "resume" && (
        <ResumeWorkspacePage
          profile={profile}
          position={activePosition}
          onUpdateResume={updateResume}
          onUpdateEvidence={updateEvidence}
          onSetHighlights={(highlights) => patchState((current) => ({ ...current, profile: { ...current.profile, highlights } }))}
          onOpenLive={() => openRoute("/live")}
          onOpenJd={() => openRoute("/jd")}
        />
      )}

      {route.name === "records" && (
        <RecordsView
          records={interviewRecords}
          positions={positions}
          onOpen={(id) => {
            patchState((current) => ({ ...current, activeRecordId: id }));
            openRoute(`/records/${id}`);
          }}
          onMock={() => startConfiguredMock()}
        />
      )}

      {route.name === "recordDetail" && (
        <RecordReportView
          record={activeRecord}
          position={positions.find((item) => item.id === activeRecord?.positionId)}
          onMock={() => startConfiguredMock()}
        />
      )}

      {accountOpen && (
        <AccountModal
          state={appState}
          onClose={() => setAccountOpen(false)}
          onImport={(next) => {
            setAppState(repairAppState(next));
            setAccountOpen(false);
          }}
          onRename={(name) => patchState((current) => ({ ...current, profile: { ...current.profile, displayName: name } }))}
          onClear={clearAll}
        />
      )}
    </AppShell>
  );
}

