type ParsedUploadItem = {
  question: string;
  answer: string;
  notes: string;
};

function parseUploadToCandidates(text: string): ParsedUploadItem[] {
  const blocks = text
    .split(/\n{2,}/)
    .map((item) => item.trim())
    .filter(Boolean);

  return blocks.slice(0, 6).map((block, index) => {
    const lines = block.split("\n").map((line) => line.trim()).filter(Boolean);
    return {
      question: lines[0] || `鍊欓€夐棶棰?${index + 1}`,
      answer: lines.slice(1, 3).join(" "),
      notes: lines.slice(3).join(" "),
    };
  });
}

