import { ArrowRight, BriefcaseBusiness, Plus } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { repairText } from "../lib/copy";
import type { Position, WorkspaceState } from "../types";

export function HomeDashboard({
  workspace,
  position,
  positions,
  activePositionId,
  drawerOpen,
  onToggleDrawer,
  onCloseDrawer,
  onSubmitJd,
  onSelectPosition,
  onLive,
  onOpenMock,
}: {
  workspace: WorkspaceState | null;
  position: Position | undefined;
  positions: Position[];
  activePositionId: string;
  drawerOpen: boolean;
  onToggleDrawer: () => void;
  onCloseDrawer: () => void;
  onSubmitJd: (jobText: string) => void;
  onSelectPosition: (positionId: string) => void;
  onLive: () => void;
  onOpenMock: () => void;
}) {
  const [draft, setDraft] = useState(workspace?.jobText ?? "");

  const orderedPositions = useMemo(() => {
    return [...positions].sort((a, b) => {
      if (a.id === activePositionId) return -1;
      if (b.id === activePositionId) return 1;
      return Date.parse(b.updatedAt) - Date.parse(a.updatedAt);
    });
  }, [activePositionId, positions]);

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    if (!draft.trim()) return;
    onSubmitJd(draft.trim());
  };

  return (
    <section className="page page-home desktop-page">
      <header className="desktop-page-header">
        <div className="desktop-page-title">
          <span className="page-eyebrow">岗位台</span>
          <h1>我的岗位</h1>
        </div>
        <button className="button primary" type="button" onClick={() => {
          setDraft(workspace?.jobText ?? "");
          onToggleDrawer();
        }}>
          <Plus size={16} />
          新增岗位
        </button>
      </header>

      {orderedPositions.length > 0 ? (
        <section className="position-board" aria-label="岗位列表">
          {orderedPositions.map((item, index) => {
            const active = item.id === activePositionId;
            const score = Math.max(0, Math.min(100, item.matchReport.score));
            const primaryTags = [
              item.job.hardSkills[0],
              item.job.softSkills[0],
              item.job.keywords[0],
            ]
              .filter(Boolean)
              .slice(0, 3);

            return (
              <button
                key={item.id}
                type="button"
                className={active ? "position-summary-card active" : "position-summary-card"}
                onClick={() => onSelectPosition(item.id)}
              >
                <span className="position-summary-rail" aria-hidden="true" />
                <div className="position-summary-main">
                  <div className="position-summary-head">
                    <div>
                      <span className="position-summary-label">{active ? "当前岗位" : index === 0 ? "最近访问" : "备用岗位"}</span>
                      <h2>
                        {repairText(item.company)} · {repairText(item.title)}
                      </h2>
                    </div>
                    <div className="position-summary-score">
                      <span>简历匹配度</span>
                      <strong>{score}%</strong>
                    </div>
                  </div>

                  <div className="position-progress-track" aria-hidden="true">
                    <span style={{ width: `${score}%` }} />
                  </div>

                  <div className="pill-row">
                    {primaryTags.map((tag) => (
                      <span key={`${item.id}-${tag}`} className="pill">
                        {repairText(tag)}
                      </span>
                    ))}
                  </div>
                </div>
              </button>
            );
          })}
        </section>
      ) : (
        <section className="empty-card compact">
          <div className="empty-card-icon">
            <BriefcaseBusiness size={18} />
          </div>
          <div>
            <h2>先新增一个岗位</h2>
            <p>粘贴 JD 后，系统会生成岗位卡，并把分析内容同步到后续页面。</p>
          </div>
          <button className="button primary" type="button" onClick={() => {
            setDraft(workspace?.jobText ?? "");
            onToggleDrawer();
          }}>
            <Plus size={16} />
            新增岗位
          </button>
        </section>
      )}

      <section className="launch-bar">
        <div className="launch-bar-actions">
          <button className="button primary" type="button" onClick={onLive} disabled={!position}>
            开启实时助手
            <ArrowRight size={16} />
          </button>
          <button className="button secondary" type="button" onClick={onOpenMock} disabled={!position}>
            模拟练习
          </button>
        </div>
      </section>

      {drawerOpen ? (
        <div className="drawer-backdrop" role="presentation" onClick={onCloseDrawer}>
          <aside className="drawer-panel" role="dialog" aria-modal="true" aria-label="新增岗位抽屉" onClick={(event) => event.stopPropagation()}>
            <header className="drawer-header">
              <div>
                <span className="page-eyebrow">新增岗位</span>
                <h2>粘贴 JD 文本</h2>
              </div>
              <button className="button ghost" type="button" onClick={onCloseDrawer}>
                关闭
              </button>
            </header>

            <form className="drawer-form" onSubmit={handleSubmit}>
              <textarea
                className="input textarea tall"
                value={draft}
                aria-label="JD 文本"
                onChange={(event) => setDraft(event.target.value)}
                placeholder="粘贴完整 JD，系统会生成岗位卡并同步后续分析。"
              />
              <div className="drawer-actions">
                <button className="button secondary" type="button" onClick={onCloseDrawer}>
                  取消
                </button>
                <button className="button primary" type="submit" disabled={!draft.trim()}>
                  生成岗位卡
                </button>
              </div>
            </form>
          </aside>
        </div>
      ) : null}
    </section>
  );
}

