      text: "告诉我你想面试的岗位、面试官、难度和时长。我会像面试搭子一样继续追问，信息够了就帮你保存 JD 和配置面试。",
    },
  ]);

  const orderedPositions = useMemo(() => {
    return [...positions].sort((a, b) => {
      if (a.id === activePositionId) return -1;
      if (b.id === activePositionId) return 1;
      return Date.parse(b.updatedAt) - Date.parse(a.updatedAt);
    });
  }, [activePositionId, positions]);

  const currentRecommendation = generatedJd.trim() ? buildDraftJd(generatedJd) : position ? buildDraftJd(position.jobText) : null;
  const activeScore = Math.max(0, Math.min(100, position?.matchReport.score ?? 0));

  const submit = (event: FormEvent) => {
    event.preventDefault();
    const text = input.trim();
    if (!text) return;
    const draft = buildDraftJd(text);
    setGeneratedJd(draft.text);
    setMessages((current) => [
      ...current,
      { id: `home-user-${current.length + 1}`, role: "user", text },
      {
        id: `home-assistant-${current.length + 2}`,
        role: "assistant",
        text: `收到。当前我先按「${draft.company} · ${draft.role} · ${draft.interviewer} · ${draft.difficulty}」生成岗位卡。如果你有完整 JD 可以继续贴进来，没有的话也可以先保存这版开始练。`,
      },
    ]);
    setInput("");
  };

  const applyPrompt = (prompt: string) => {
    setInput(prompt);
  };

  const saveJd = () => {
    const text = generatedJd.trim() || position?.jobText.trim();
    if (text) onSubmitJd(text);
  };

  const configureInterview = () => {
    const role = currentRecommendation?.interviewer;
    onOpenMock({
      interviewerRole: role === "HR" || role === "CTO" || role === "CEO" || role === "业务负责人" || role === "上级" ? role : "上级",
      difficulty: currentRecommendation?.difficulty === "地狱面" ? "地狱面" : currentRecommendation?.difficulty === "压力面" ? "压力面" : "正常",
      interviewerGender: "女",
      submitMode: "manual",
      style: currentRecommendation?.difficulty === "压力面" || currentRecommendation?.difficulty === "地狱面" ? "pressure" : "gentle",
    });
  };

  return (
    <section className="page page-home desktop-page lollipop-home">
      <div className="home-conversation-shell">
        <header className="home-hero">
          <span className="page-eyebrow">岗位台</span>
          <h1>告诉我你想面试的岗位</h1>
          <p>我会基于对话细化目标岗位、面试官和难度，信息够了就保存 JD 并配置模拟面试。</p>
        </header>

        <form className="home-intake-box" onSubmit={submit}>
          <textarea
            value={input}
            aria-label="岗位对话输入"
            onChange={(event) => setInput(event.target.value)}
            placeholder="例如：字节 AI 产品经理终面，业务负责人面我，正常难度，30 分钟"
          />
          <div className="home-intake-actions">
            <button className="button secondary" type="button">
              <Upload size={16} />
              上传自定义 JD
            </button>
            <button className="button primary" type="submit" disabled={!input.trim()}>
              发送
              <ArrowRight size={16} />
            </button>
          </div>
        </form>

        <div className="home-prompt-row" aria-label="推荐输入">
          {["我想面字节的 AI 产品经理", "我是设计师，想面 AIGC 方向", "根据我的简历推荐岗位"].map((prompt) => (
            <button key={prompt} type="button" className="prompt-chip" onClick={() => applyPrompt(prompt)}>
              <MessageCircle size={15} />
              {prompt}
            </button>
          ))}
        </div>

        <div className="home-conversation-grid">
          <main className="home-dialog-column">
            <div className="home-thread">
              {messages.map((message) => (
                <article key={message.id} className={message.role === "assistant" ? "chat-bubble assistant" : "chat-bubble user"}>
                  <p>{message.text}</p>
                </article>
              ))}
            </div>

            <section className="home-recommendation">
              <header>
                <span className="assistant-badge">
                  <Sparkles size={14} />
                  推荐岗位卡
                </span>
                <strong>{currentRecommendation ? `${currentRecommendation.role}（${currentRecommendation.company}）` : "等你告诉我目标岗位"}</strong>
              </header>
              {currentRecommendation ? (
                <>
                  <p>{currentRecommendation.text}</p>
                  <div className="home-card-actions">
                    <button className="button secondary" type="button" onClick={saveJd}>
                      <Save size={16} />
                      保存到我的岗位
                    </button>
                    <button className="button primary" type="button" onClick={configureInterview}>
                      <Settings2 size={16} />
                      配置面试
                    </button>
                  </div>
                </>
              ) : (
                <p>你可以直接说目标公司、岗位方向、面试官、难度和时长；缺的信息我会继续问。</p>
              )}
            </section>
          </main>

          <aside className="home-context-panel">
            <div className="home-context-header">
              <BriefcaseBusiness size={18} />
              <div>
                <span>当前岗位</span>
                <strong>{position ? `${repairText(position.company)} · ${repairText(position.title)}` : "还未保存岗位"}</strong>
              </div>
            </div>
            <div className="home-context-stats">
              <article>
                <span>简历匹配</span>
                <strong>{position ? `${activeScore}%` : "--"}</strong>
              </article>
              <article>
                <span>资料卡</span>
                <strong>{position?.materials.length ?? 0}</strong>
              </article>
              <article>
                <span>高频题</span>
                <strong>{position?.questions.filter((item) => item.priority).length ?? 0}</strong>
              </article>
            </div>
            <div className="home-intake-fields">
              {position ? (
                ["experience", "interviewer", "difficulty", "duration"].map((key) => (
                  <div key={key}>
                    <Check size={14} />
                    <span>{fieldValue(position, key)}</span>
                  </div>
                ))
              ) : (
                <p>保存 JD 后，这里会显示岗位配置、资料数量和准备重点。</p>
              )}
            </div>
            {orderedPositions.length > 0 ? (
              <div className="home-position-switcher">
                {orderedPositions.slice(0, 4).map((item) => (
                  <button key={item.id} type="button" className={item.id === activePositionId ? "active" : ""} onClick={() => onSelectPosition(item.id)}>
                    <span>{repairText(item.company)}</span>
                    <strong>{repairText(item.title)}</strong>
                  </button>
                ))}
              </div>
            ) : null}
          </aside>
        </div>
      </div>
    </section>
  );
}

