  useEffect(() => {
    const onResize = () => setIsMobile(window.innerWidth <= 900);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  return isMobile;
}

export function AppShell({
  activeNav,
  accountName,
  onNavigate,
  onAccount,
  children,
}: {
