  const curated = previous.evidenceLibrary.filter((item) => item.id.startsWith("ev-custom-"));
  const merged = mergeEvidence(next.evidenceLibrary, curated);
  return { ...next, evidenceLibrary: merged, highlights: previous.highlights };
