+  const matches = text.match(/[A-Za-z][A-Za-z0-9+#./-]{1,}|[\u4e00-\u9fa5]{2,}/g) ?? [];
+  const seen = new Set<string>();
+  return matches
+    .map((item) => item.trim())
+    .filter((item) => {
+      const key = item.toLowerCase();
+      if (seen.has(key)) return false;
+      seen.add(key);
+      return item.length <= 20;
+    })
+    .slice(0, limit);
