import { ArrowRight, FileSearch, Sparkles } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { repairText } from "../lib/copy";
import type { CandidateProfile, Position, WorkspaceState } from "../types";

type JdChatMessage = {
  id: string;
  role: "assistant" | "user";
  text: string;
};

function buildJdReply(question: string, workspace: WorkspaceState | null, profile: CandidateProfile): string {
  const normalized = question.toLowerCase();
  if (!workspace) return "先创建一个岗位，我再围绕当前 JD 帮你拆解重点。";

  if (normalized.includes("更看重") || normalized.includes("重点")) {
    return `这个岗位当前最看重 ${workspace.job.hardSkills.slice(0, 3).join("、") || "核心业务理解"}，其次是 ${workspace.job.softSkills.slice(0, 2).join("、") || "表达与协作"}。你在回答时要把经历主动对齐到这些关键词。`;
  }
  if (normalized.includes("差距") || normalized.includes("最弱")) {
    const gap = workspace.matchReport.gaps.find((item) => item.type !== "match");
    return gap ? `你当前最明显的短板是“${gap.label}”。${gap.description}` : "目前没有特别突出的硬性短板，建议优先强化可量化结果和个人贡献边界。";
  }
  if (normalized.includes("高频题") || normalized.includes("5 道")) {
    return workspace.questions
      .slice(0, 5)
      .map((item, index) => `${index + 1}. ${repairText(item.question)}`)
      .join("\n");
  }
  if (normalized.includes("简历") || normalized.includes("证据")) {
    return `当前和这个 JD 最相关的简历证据包括：${profile.evidenceLibrary.slice(0, 3).map((item) => item.title).join("、")}。建议优先用这些经历回答项目深挖和专业技能题。`;
  }
  return "我建议你围绕岗位要求、个人证据和表达短板三个维度继续追问，例如“这个岗位最看重什么”“我最弱的是哪块”“给我 5 道高频题”。";
}

export function JdWorkspace({
  workspace,
  profile,
  position,
  onSubmitJd,
  onOpenLive,
  onOpenMock,
  onCreateQuestions,
}: {
  workspace: WorkspaceState | null;
  profile: CandidateProfile;
  position?: Position;
  onSubmitJd: (jobText: string) => void;
  onOpenLive: () => void;
  onOpenMock: () => void;
  onCreateQuestions: (items: Array<{ question: string; category: string; difficulty: string; notes?: string }>) => void;
}) {
  const [draft, setDraft] = useState(workspace?.jobText ?? "");
  const [chatInput, setChatInput] = useState("");
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [messages, setMessages] = useState<JdChatMessage[]>([
    { id: "jd-assistant-1", role: "assistant", text: "你可以问我：这个岗位更看重什么、我最弱的是哪块、给我 5 道高频题。" },
  ]);

  const insightGroups = useMemo(() => {
    if (!workspace) return [];
    return [
      { title: "简历差异", items: workspace.matchReport.gaps.slice(0, 5).map((item) => `${repairText(item.label)}：${repairText(item.description)}`), defaultOpen: true },
      { title: "核心技能", items: workspace.job.hardSkills.slice(0, 6), defaultOpen: false },
      { title: "软性要求", items: workspace.job.softSkills.slice(0, 6), defaultOpen: false },
      { title: "隐藏信号", items: workspace.job.hiddenSignals.slice(0, 6), defaultOpen: false },
    ];
  }, [workspace]);

  const keywords = workspace?.job.keywords.slice(0, 12) ?? [];
  const visibleKeywords = keywords.slice(0, 6);
  const hiddenKeywords = keywords.slice(6);

  const submitJd = (event: FormEvent) => {
    event.preventDefault();
    if (!draft.trim()) return;
    onSubmitJd(draft.trim());
  };

  const sendChat = (event: FormEvent) => {
    event.preventDefault();
    const question = chatInput.trim();
    if (!question) return;
    const reply = buildJdReply(question, workspace, profile);
    setMessages((current) => [
      ...current,
      { id: `jd-user-${current.length + 1}`, role: "user", text: question },
      { id: `jd-assistant-${current.length + 2}`, role: "assistant", text: reply },
    ]);
    setChatInput("");
  };

  const saveSuggestedQuestions = () => {
    if (!workspace) return;
    onCreateQuestions(
      workspace.questions.slice(0, 5).map((item) => ({
        question: item.question,
        category: item.category,
        difficulty: item.difficulty,
        notes: "来自 JD 分析页推荐问题。",
      })),
    );
  };

  return (
    <section className="page page-jd desktop-page">
      <header className="desktop-page-header">
        <div className="desktop-page-title">
          <span className="page-eyebrow">JD 分析</span>
          <h1>岗位分析</h1>
        </div>
        <div className="hero-actions">
          <button className="button secondary" type="button" onClick={() => setDrawerOpen(true)}>
            分析对话
          </button>
          <button className="button secondary" type="button" onClick={onOpenMock} disabled={!workspace}>
            模拟练习
          </button>
          <button className="button primary" type="button" onClick={onOpenLive} disabled={!workspace}>
            开启实时助手
            <ArrowRight size={16} />
          </button>
        </div>
      </header>

      <div className="two-column-layout jd-page-layout">
        <section className="surface-card jd-analysis-column">
          <div className="surface-card-inner">
            <div className="section-row-header">
              <div>
                <span className="subtle-label">分析结果</span>
                <h2>{position ? `${repairText(position.company)} · ${repairText(position.title)}` : "还没有岗位"}</h2>
              </div>
              <button className="button secondary" type="button" onClick={saveSuggestedQuestions} disabled={!workspace}>
                保存 5 道高频题
              </button>
            </div>

            {workspace ? (
              <div className="analysis-stack">
                <section className="analysis-panel">
                  <strong>关键词</strong>
                  <div className="pill-row">
                    {visibleKeywords.map((item) => (
                      <span key={item} className="pill">{repairText(item)}</span>
                    ))}
                  </div>
                  {hiddenKeywords.length > 0 ? (
                    <details className="keyword-inline-expand">
                      <summary>展开更多关键词</summary>
                      <div className="pill-row">
                        {hiddenKeywords.map((item) => (
                          <span key={item} className="pill">{repairText(item)}</span>
                        ))}
                      </div>
                    </details>
                  ) : null}
                </section>

                {insightGroups.map((group) => (
                  <details key={group.title} className="analysis-collapse" open={group.defaultOpen}>
                    <summary>{group.title}</summary>
                    <ul className="simple-list">
                      {group.items.length > 0 ? group.items.map((item) => <li key={item}>{repairText(item)}</li>) : <li>暂无数据</li>}
                    </ul>
                  </details>
                ))}

                <details className="analysis-collapse">
                  <summary>JD 原文</summary>
                  <form className="drawer-form inline-form" onSubmit={submitJd}>
                    <textarea
                      className="input textarea tall"
                      value={draft}
                      aria-label="JD 文本"
                      onChange={(event) => setDraft(event.target.value)}
                      placeholder="粘贴当前岗位 JD，更新后左侧分析会同步刷新。"
                    />
                    <div className="drawer-actions">
                      <button className="button primary" type="submit" disabled={!draft.trim()}>
                        更新分析
                      </button>
                    </div>
                  </form>
                </details>
              </div>
            ) : (
              <div className="empty-card compact">
                <div className="empty-card-icon">
                  <FileSearch size={18} />
                </div>
                <div>
                  <h2>先生成一个岗位卡</h2>
                  <p>有了当前岗位后，这里会展示 JD 关键词、要求分层、简历差异和推荐问题。</p>
                </div>
              </div>
            )}
          </div>
        </section>
      </div>

      {drawerOpen ? (
        <div className="drawer-backdrop" role="presentation" onClick={() => setDrawerOpen(false)}>
          <aside className="drawer-panel narrow" role="dialog" aria-modal="true" aria-label="岗位分析对话" onClick={(event) => event.stopPropagation()}>
            <header className="drawer-header">
              <div>
                <span className="page-eyebrow">分析对话</span>
                <h2>岗位分析助手</h2>
              </div>
              <span className="assistant-badge">
                <Sparkles size={14} />
                窄域助手
              </span>
            </header>

            <div className="chat-thread">
              {messages.map((message) => (
